  ('qingdao-scaffolding', 'scaffolding', 'Factory Price Concrete Wall Formwork System 45# Steel Panel Pj63 Euro Form', null, 'Factory Price Concrete Wall Formwork System 45# Steel Panel Pj63 Euro Form. Manual Assembly Design: Handset light weight steel frame panel formwork assembled without crane. High Reusability: Reusable for more than 300 times with durable construction. Versatile Dimensions: Offers heights up to 3.3 meters and widths up to 0.9 meters. High Pressure Resistance: Permissible concrete pressure up to 60 KN/M2 for safety. Premium Material: Constructed with high-quality Aluminium alloy 6061-T6. Global Project Experience: Successfully used in over 500 projects across multiple continents. Comprehensive Certifications: Holds ISO, CE, BIZSAFE, TUV, and BCA-BAND2 certifications. Cost Effective Solution: Lower cost and environment friendly for residential construction.', null, '[{"label_en":"Material","label_es":"Material","value":"Concrete"},{"label_en":"Type","label_es":"Tipo","value":"Wall Formwork"},{"label_en":"After-Sale Service","label_es":"After-Sale Service","value":"Online Technical Support, Onsite Training"},{"label_en":"Project Solution Capability","label_es":"Project Solution Capability","value":"Graphic Design, Total Solution for Projects"},{"label_en":"Application","label_es":"Aplicación","value":"Civill Construction"},{"label_en":"Color","label_es":"Color","value":"Aluminum"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"No"},{"label_en":"Thickness","label_es":"Espesor","value":"120mm"}]', 'piece', 4999, 15, 99, array['https://image.made-in-china.com/203f0j00AQMCKzOswSop/Factory-Price-Concrete-Wall-Formwork-System-45-Steel-Panel-Pj63-Euro-Form.webp', 'https://image.made-in-china.com/203f0j00mQveKhydPjku/Factory-Price-Concrete-Wall-Formwork-System-45-Steel-Panel-Pj63-Euro-Form.webp', 'https://image.made-in-china.com/203f0j00BlRvHweSLYob/Factory-Price-Concrete-Wall-Formwork-System-45-Steel-Panel-Pj63-Euro-Form.