  ('lianggongformwork', 'scaffolding', 'High Quality 6061-T6 Aluminum Alloy Frame Concrete Construction Formwork for Wall and Column', null, 'High Quality 6061-T6 Aluminum Alloy Frame Concrete Construction Formwork for Wall and Column. High-Strength Material: Manufactured with high-strength 6061-T6 aluminum alloy for durability. Lightweight Design: Panels are lightweight and can be moved by hand for easy handling. Rapid Assembly: Easy assembly with clamps without alignment walers for quick installation. High Pressure Resistance: Designed for an allowable concrete pressure of 60KN/m2. Durable Surface: All panels are powder-coated to enhance lifespan and corrosion resistance. Multiple Standard Sizes: Available in 12 standard sizes with heights of 3000, 2500, and 1250mm. Long Reusability: Reusable for 5 to 10 years depending on usage conditions. Comprehensive Support: Includes online technical support, onsite installation, and remote guidance.', null, '[{"label_en":"Material","label_es":"Material","value":"Aluminum"},{"label_en":"Type","label_es":"Tipo","value":"Wall Formwork"},{"label_en":"Reusable Times","label_es":"Reusable Times","value":"5~10 Years Reusable"},{"label_en":"Aplication","label_es":"Aplication","value":"Highway, Railway, Bridges"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"Spray Painted"},{"label_en":"Materials","label_es":"Materials","value":"Aluminum 6061t"},{"label_en":"Surface","label_es":"Surface","value":"Powder Coated"},{"label_en":"Application","label_es":"Aplicación","value":"Hotel, Wall, Column, Core Tube, etc"}]', 'm2', 200, 15, 100, array['https://image.made-in-china.com/203f0j00LAQMfVRFhWkD/High-Quality-6061-T6-Aluminum-Alloy-Frame-Concrete-Construction-Formwork-for-Wall-and-Column.webp', 'https://image.made-in-china.com/203f0j00jwJWBYlRhuUt/High-Quality-6061-T6-Aluminum-Alloy-Frame-Concrete-Construction-Formwork-for-Wall-and-Column.webp', 'https://image.made-in-china.com/203f0j00jAJVeHWhAzfQ/High-Qual