  ('lianggongformwork', 'scaffolding', 'H20 Timber Beam Wooden Aluminium Plastic Steel Slab Concrete Formwork for Construction', null, 'H20 Timber Beam Wooden Aluminium Plastic Steel Slab Concrete Formwork for Construction. Customized Size and Color: Available in customized dimensions and yellow color options to fit specific project needs. ISO Certification: Product meets international ISO quality standards for safety and reliability. Flexible and Cuttable Design: Easy to assemble, disassemble, and cut to fit intricate floor layouts and limited spaces. High Reusability: Designed for multiple uses without disassembly, significantly reducing labor investment. Lightweight Construction: Timber beam weighs 5.2kg/M, making it easy to handle and operate autonomously from cranes. One-Stop After-Sales Service: Comprehensive support including remote or on-site instruction and design consultation. High Bearing Capacity: Supports 5-15kN per square meter, suitable for high-rise and super-high-rise buildings.', null, '[{"label_en":"Material","label_es":"Material","value":"Timber"},{"label_en":"Type","label_es":"Tipo","value":"Slab Formwork"},{"label_en":"Color","label_es":"Color","value":"Yellow,Customized"},{"label_en":"Size","label_es":"Tamaño","value":"Customized"},{"label_en":"Feature","label_es":"Feature","value":"Flexible,Cuttable"},{"label_en":"Concrete Surface","label_es":"Concrete Surface","value":"Flat"},{"label_en":"Timber Beam Weight","label_es":"Timber Beam Weight","value":"5.2kg/M"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"Painted"},{"label_en":"Thickness of Plywood","label_es":"Thickness of Plywood","value":"15mm,18mm"},{"label_en":"Bearing Capacity","label_es":"Bearing Capacity","value":"5-15kN/Square Meter"}]', 'm2', 1, 15, 60, array['https://image.made-in-china.com/203f0j00DmtvLTfsChcN/H20-Timber-Beam-Wooden-Aluminium-Plastic-Steel-Slab-Concrete-Formwork-for-Construction.webp', 'https://image.made-in-china.com/203f0j00eHvMy