  ('lianggongformwork', 'scaffolding', 'China Supplier Flexible Integrated H20 Timber Beam Table Formwork for Construction', null, 'China Supplier Flexible Integrated H20 Timber Beam Table Formwork for Construction. Customized Dimensions: Size is fully customizable to meet specific project requirements. Customized Color Options: Available in Yellow or other customized colors upon request. Flexible and Cuttable: Features flexible design and cuttable capability for versatile application. Reusable Design: Lifted to upper levels without dismantling, saving manpower and time. One-Stop After-Sales Service: Comprehensive support including consulting, design, and on-site instruction. ISO Certified Quality: Manufactured with ISO certification ensuring high standards and compliance. 1-Year Warranty: Covers mechanical defects for a period of one year from purchase. Fast Design Turnaround: Preliminary design and quotation provided within 5 to 7 days.', null, '[{"label_en":"Material","label_es":"Material","value":"Timber"},{"label_en":"Type","label_es":"Tipo","value":"Slab Formwork"},{"label_en":"Color","label_es":"Color","value":"Yellow, Customized"},{"label_en":"Size","label_es":"Tamaño","value":"Customized"},{"label_en":"Feature","label_es":"Feature","value":"Flexible, Cuttable"},{"label_en":"Concrete Surface","label_es":"Concrete Surface","value":"Flat"},{"label_en":"Timber Beam Weight","label_es":"Timber Beam Weight","value":"5.2kg/M"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"Painted"},{"label_en":"Thickness of Plywood","label_es":"Thickness of Plywood","value":"15mm, 18mm"},{"label_en":"Bearing Capacity","label_es":"Bearing Capacity","value":"5-15kN/Square Meter"}]', 'm2', 100, 15, 47, array['https://image.made-in-china.com/203f0j00NwsBdKHPpLbu/China-Supplier-Flexible-Integrated-H20-Timber-Beam-Table-Formwork-for-Construction.webp', 'https://image.made-in-china.com/203f0j00RIJBisDdktkF/China-Supplier-Flexible-Integrated-H20-Timber-Bea