  ('lianggongformwork', 'scaffolding', 'Customized Adaptable Corrosion-Resistant Hydraulic Auto-Climbing Formwork for Varied Conditions', null, 'Customized Adaptable Corrosion-Resistant Hydraulic Auto-Climbing Formwork for Varied Conditions. Hydraulic Self-Climbing System: Powered by own hydraulic jacking system for steady, safe, and fast upward climbing without external lifting equipment. Versatile Climbing Capabilities: Capable of climbing straight or diagonally, suitable for high-rise buildings and bridge construction. Integrated Operation Platform: Provides all-round operation platform, eliminating need for re-building and improving construction safety. High Safety and Efficiency: Smooth, synchronized climbing process with high safety factor and reduced tower crane lifting time. Customizable Design: Offers full customization, minor customization, and flexible customization options based on samples or designs. ISO Certified Quality: Manufactured with ISO certification and 100% visual and function inspection for finished products. Comprehensive After-Sales Support: Includes online technical support and onsite installation services with remote or on-site guidance available. 1-Year Warranty Coverage: Provides a 1-year warranty period for all mechanical equipment and components.', null, '[{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Climbing Formwork"},{"label_en":"Application","label_es":"Aplicación","value":"High-Rise Building and Bridge Construction"},{"label_en":"Bracket Height","label_es":"Bracket Height","value":"10.1~17.3 Meters"},{"label_en":"Climbing Height","label_es":"Climbing Height","value":"3~6 Meters"},{"label_en":"Climbing Speed","label_es":"Climbing Speed","value":"4.5~6 Meters/Hour"},{"label_en":"Rated Pressuret","label_es":"Rated Pressuret","value":"16 MPa"},{"label_en":"Design","label_es":"Design","value":"Lianggong"}]', 'set', 1, 15, 2999, array['https://image.made-in-china.com/203f0j