  ('lianggongformwork', 'scaffolding', 'Lianggong Durable Resusable Hydraulic Climbing Formwork for High Rise Building Bridges', null, 'Lianggong Durable Resusable Hydraulic Climbing Formwork for High Rise Building Bridges. Self-Climbing Capability: Reduces lifting machinery workload and speeds up construction for towering structures. Customizable Colors: Available in Blue, Red, or fully customized color options to meet project needs. ISO Certified Quality: Manufactured with ISO certification ensuring high standards and reliability. One Year Warranty: Comprehensive one-year warranty coverage for peace of mind. Online Technical Support: Dedicated online support team available for assistance and troubleshooting. High Stiffness Frame: Superior frame stiffness ensures stable structure during the climbing process. Low Friction Design: Formwork breaks away from concrete surface as it climbs, reducing friction. Fast Modular Assembly: Simple assembly speed allows for quick and efficient construction setup.', null, '[{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Climbing Formwork"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"Painted"},{"label_en":"Colour","label_es":"Colour","value":"Blue,Red,Customized"},{"label_en":"Concrete Surface","label_es":"Concrete Surface","value":"Smooth"},{"label_en":"Function","label_es":"Function","value":"Strengthen"},{"label_en":"Assembly Speed","label_es":"Assembly Speed","value":"Simple"}]', 'ton', 200, 15, 1000, array['https://image.made-in-china.com/203f0j00RpCKqteWrscA/Lianggong-Durable-Resusable-Hydraulic-Climbing-Formwork-for-High-Rise-Building-Bridges.webp', 'https://image.made-in-china.com/203f0j00lMcCqFbIkzoB/Lianggong-Durable-Resusable-Hydraulic-Climbing-Formwork-for-High-Rise-Building-Bridges.webp', 'https://image.made-in-china.com/203f0j00kUHvReFnLBoh/Lianggong-Durable-Resusable-Hydraulic-Climbing-Formwork-for-High-Rise-Building-Bridg