  ('lianggongformwork', 'scaffolding', 'Cantilever Climbing Jump Wall Concrete Construction Formwork for High Rise Building', null, 'Cantilever Climbing Jump Wall Concrete Construction Formwork for High Rise Building. No Additional Scaffolding: Load borne by embedded anchors and tie rods, eliminating need for extra scaffolding. Wide Application Range: Suitable for dams, piers, retaining walls, tunnels, basements, and high-rise buildings. High Standardization: Connecting parts feature high standardization and versatility for easy assembly. Adjustable Design: Formwork adjusts up/down, left/right, and tilts back/forth to fit concrete surfaces. Smooth Concrete Finish: Ensures smooth concrete surface and prevents leaking or misalignment during pouring. Customizable Color: Available in Blue, Red, or customized colors to meet specific project requirements. Professional Support: Provides remote or on-site installation guidance and technical support. Durable Construction: Steel material with painted surface ensures economy and durability for long-term use.', null, '[{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Climbing Formwork"},{"label_en":"Rack Height","label_es":"Rack Height","value":"10~15 Meters"},{"label_en":"Surface","label_es":"Surface","value":"Painted"},{"label_en":"Color","label_es":"Color","value":"Blue,Red , Customized"},{"label_en":"Application","label_es":"Aplicación","value":"High-Rise Building and Bridge Construction"},{"label_en":"Climbing Height","label_es":"Climbing Height","value":"3~6 Meters/Time"}]', 'piece', 1, 15, 480, array['https://image.made-in-china.com/203f0j00hUsSqKgWrzbO/Cantilever-Climbing-Jump-Wall-Concrete-Construction-Formwork-for-High-Rise-Building.webp', 'https://image.made-in-china.com/203f0j00DncMkmuHLjoa/Cantilever-Climbing-Jump-Wall-Concrete-Construction-Formwork-for-High-Rise-Building.webp', 'https://image.made-in-china.com/203f0j00eCfblnHaaQzc/Cantilever-Climbing-Jump-