  ('aluscaffold', 'scaffolding', 'Engineered Scaffolding & Formwork for Dubai Sea Bridge Projects', null, 'Engineered Scaffolding & Formwork for Dubai Sea Bridge Projects. EN12810 Certified Safety: Meets EN12810 standards for heavy-duty ringlock scaffolding systems. High-Quality Steel Material: Constructed from Q235/Q355 carbon steel with HDG finish for durability. Modular Ringlock System: Multi-pole design with vertical, ledger, and diagonal braces for stability. Comprehensive OEM/ODM Support: Offers full customization, minor customization, and design-based options. ISO Quality Management: Certified with ISO9001:2015, ISO45001:2018, and ISO14001 standards. 100% Finished Product Inspection: Rigorous visual inspection by 10 QA/QC inspectors ensures zero defects. Flexible Payment Terms: Accepts LC, T/T, D/P, PayPal, Western Union, and small-amount payments. Global Shipping Capability: Exports to North America, Europe, and other regions via Shanghai Port.', null, '[{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Fixed"},{"label_en":"Structural Style","label_es":"Structural Style","value":"Multi-Pole Scaffolding"},{"label_en":"Framework","label_es":"Framework","value":"Combined Scaffolding"},{"label_en":"Supporting Mode","label_es":"Supporting Mode","value":"Projecting Scaffolding"},{"label_en":"Lapping Form","label_es":"Lapping Form","value":"Full Scaffolding"},{"label_en":"Erection Position","label_es":"Erection Position","value":"External Scaffolding"},{"label_en":"Move Method","label_es":"Move Method","value":"Attached Lifting Scaffolding"},{"label_en":"Scaffolding Part Type","label_es":"Scaffolding Part Type","value":"Scaffolding Props"},{"label_en":"Construction Properties","label_es":"Construction Properties","value":"Installation Scaffold"}]', 'piece', 30, 15, 3.87, array['https://image.made-in-china.com/203f0j00WGiZEmsBCakH/Engineered-Scaffolding-Formwork-for-Dubai-Sea-Bridge-Projects.webp', 'https://i