  ('lianggongform', 'scaffolding', 'Lianggong Durable Steel Tunnel Formwork for Constructing Cellular Building', null, 'Lianggong Durable Steel Tunnel Formwork for Constructing Cellular Building. Monolithic Structure: Combines wall and floor casting for high seismic resistance and improved water tightness. Rapid Construction Cycle: Achieves slab casting in 1-2 days, up to 3 times faster than conventional methods. Customized Surface Treatment: Surface treatment is fully customized to meet specific project requirements. High Quality Finish: Produces smooth fair-faced concrete finish requiring minimal preparation for decoration. Cost Efficiency: Reduces labor costs, mobilization costs, and fine-structure labor expenses. Safety Features: Includes integral working platforms and edge protection systems for site safety. ISO Certification: Manufactured with ISO certification ensuring high quality standards. Customization Options: Offers full customization, minor customization, and flexible customization based on designs.', null, '[{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Tunnel Formwork"},{"label_en":"Materials","label_es":"Materials","value":"Steel Q235"},{"label_en":"Application","label_es":"Aplicación","value":"Hotel, Wall, Column, Core Tube, etc"},{"label_en":"Place of Origin","label_es":"Place of Origin","value":"Jiangsu, China"},{"label_en":"Surface Treatment","label_es":"Tratamiento de superficie","value":"Customised"},{"label_en":"Weight","label_es":"Peso","value":"800kg"}]', 'ton', 10, 35, 1399, array['https://image.made-in-china.com/203f0j00awgWpmIFhrRi/Lianggong-Durable-Steel-Tunnel-Formwork-for-Constructing-Cellular-Building.webp', 'https://image.made-in-china.com/203f0j00YmaWKAcfaRGu/Lianggong-Durable-Steel-Tunnel-Formwork-for-Constructing-Cellular-Building.webp', 'https://image.made-in-china.com/203f0j00WwkblgihZQqo/Lianggong-Durable-Steel-Tunnel-Formwork-for-Constructing-Cellular-Building.webp