  ('sfjxmachinery', 'led-lighting', '4600W LED Super Bright for Night Construction Signal Portable LED Light Tower', null, '4600W LED Super Bright for Night Construction Signal Portable LED Light Tower. High Power Output: Available in 4*300W, 14*500W, or 14*600W configurations with up to 78000Lm total lumen. Hydraulic Lifting System: Manual hydraulic lift reaches 7 meters height with flexible angle adjustment. Durable Construction: Made of high-quality steel, rainproof, water-spraying, and wind-resistant up to 90 km/h. Mobile & Trailer-Mounted: Portable design suitable for engineering construction, emergency rescue, and special occasions. Long Continuous Operation: Fuel tank capacity of 100 litres supports up to 120 hours of continuous work. OEM/ODM Customization: Full customization available from samples or designs to meet specific requirements. 24-Hour Technical Support: Dedicated after-sales service available via phone and email around the clock. Manufacturer Direct: 22 years of specialized experience with direct factory sales and export standard packaging.', null, '[{"label_en":"Battery Type","label_es":"Battery Type","value":"LED"},{"label_en":"Lifting Height","label_es":"Lifting Height","value":"5-10m"},{"label_en":"Portability","label_es":"Portability","value":"Mobile"},{"label_en":"Power Source","label_es":"Power Source","value":"Generator"},{"label_en":"Product Name","label_es":"Product Name","value":"Trailer Light Tower"},{"label_en":"Application","label_es":"Aplicación","value":"High Altitude Lighting"},{"label_en":"Type of Light","label_es":"Type of Light","value":"LED"},{"label_en":"Lighting System","label_es":"Lighting System","value":"Manual"},{"label_en":"Light Pole","label_es":"Light Pole","value":"Steel Pole"},{"label_en":"Fuel Tank Capacity","label_es":"Fuel Tank Capacity","value":"100 Litres"}]', 'piece', 1, 15, 2700, array['https://image.made-in-china.com/203f0j00peJoiYZgbBzR/4600W-LED-Super-Bright-for-Night-Construction-Signal-Portable-LED-Ligh