  ('tiantaiformwork', 'scaffolding', 'Premium Adjustable Scaffolding Clamp Coupler for Safe Construction', null, 'Premium Adjustable Scaffolding Clamp Coupler for Safe Construction. High-Strength Material: Constructed from Q355B steel for superior load-bearing capacity and durability. Corrosion Resistance: Hot-dip galvanized finish ensures excellent protection against rust and corrosion. Adjustable Design: Telescopic structure adapts to various distances between scaffolding and building facades. Secure Locking: Wedge-type locking design prevents loosening during use for firm joint connection. Easy Installation: Simple operation requiring only one hammer for quick locking or removal. Lightweight Construction: Reduces labor costs and facilitates easy manual handling and transportation. Safety Compliance: Meets national safety standards with third-party inspection reports available. Customizable Finish: Available in Galvanized or Gold Color surface finishes.', null, '[{"label_en":"Connection Type","label_es":"Connection Type","value":"Clamp Connection"},{"label_en":"Finish","label_es":"Finish","value":"Galvanized"},{"label_en":"Material","label_es":"Material","value":"Steel"},{"label_en":"Type","label_es":"Tipo","value":"Scaffold Couplers"},{"label_en":"Surface Finish","label_es":"Surface Finish","value":"Galvanized/ Gold Color"},{"label_en":"Size","label_es":"Tamaño","value":"Swivel"},{"label_en":"Weight","label_es":"Peso","value":"0.85-1.1kg"},{"label_en":"MOQ","label_es":"MOQ","value":"1000 Picecs"},{"label_en":"Application","label_es":"Aplicación","value":"Office Building, Hospital, School, Mall, Apartment"}]', 'piece', 1000, 15, 2.6, array['https://image.made-in-china.com/203f0j00OmkcqoulLCrg/Premium-Adjustable-Scaffolding-Clamp-Coupler-for-Safe-Construction.webp', 'https://image.made-in-china.com/203f0j00OmkcqSrafCgz/Premium-Adjustable-Scaffolding-Clamp-Coupler-for-Safe-Construction.webp', 'https://image.made-in-china.com/203f0j00nJqbcAzBwvug/Premium-Adjustable-S